"""Exports. Every export states its data origin. CSV cells are protected against spreadsheet formula injection."""
from __future__ import annotations

import csv
import hashlib
import html
import io
import json
from pathlib import Path
from typing import Any

from .. import APP_VERSION, ENGINE_VERSION
from ..engine.events import Event

_FORMULA_PREFIX = ("=", "+", "-", "@", "\t", "\r", "\n")
ORIGIN_TEXT = {
    "simulated": "SIMULATED: generated by this application's simulation engine. Not a record of human activity.",
    "synthetic": "SYNTHETIC: artificial data supplied or generated for testing. Not a record of human activity.",
    "imported": "IMPORTED: loaded from an external, user-authorized dataset. Provenance is as stated by the importer.",
    "captured": "CAPTURED: recorded by this application from input made in its own editor.",
}


def csv_cell(v: Any) -> Any:
    """Neutralize formula injection: text beginning with = + - @ (or control chars) is prefixed with an apostrophe.
    Non-string values (numbers, None) pass through unchanged; None becomes an empty cell."""
    if v is None:
        return ""
    if isinstance(v, str) and v.startswith(_FORMULA_PREFIX):
        return "'" + v
    return v


def to_csv(header: list[str], rows: list[list[Any]]) -> str:
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\r\n")
    w.writerow(header)
    for r in rows:
        w.writerow([csv_cell(c) for c in r])
    return buf.getvalue()


def events_csv(session_id: str, origin: str, events: list[Event]) -> str:
    header = ["session_id", "data_origin", "seq", "t_ms", "kind", "source", "pos", "removed_chars", "inserted_chars",
              "removed", "inserted", "duration_ms", "category"]
    rows = [[session_id, origin, e.seq, e.t_ms, e.kind, e.source, e.pos, len(e.removed), len(e.inserted), e.removed,
             e.inserted, e.duration_ms, e.meta.get("category", "")] for e in events]
    return to_csv(header, rows)  # blank t_ms means "not recorded"


def metrics_csv(rows: list[tuple[str, str, dict[str, dict[str, Any]]]]) -> str:
    """rows: (session_id, data_origin, features-by-extractor)."""
    header = ["session_id", "data_origin", "extractor", "extractor_version", "metric", "status", "value", "note"]
    out: list[list[Any]] = []
    for sid, origin, res in rows:
        for ex_id, r in res.items():
            for f in r["features"]:
                v = f["value"]
                out.append([sid, origin, ex_id, r["version"], f["name"], f["status"],
                            json.dumps(v, sort_keys=True, ensure_ascii=False) if isinstance(v, (dict, list)) else v, f.get("note", "")])
    return to_csv(header, out)


def dataset_json(name: str, sessions: list[dict[str, Any]]) -> str:
    """Stable schema ``wpl.dataset/1`` (see docs/export-formats.md)."""
    doc = {"schema": "wpl.dataset/1", "name": name, "app_version": APP_VERSION, "engine_version": ENGINE_VERSION,
           "provenance_notice": "Every session carries data_origin. Simulated/synthetic data is not human activity.",
           "sessions": sessions}
    return json.dumps(doc, indent=2, sort_keys=True, ensure_ascii=False)


def session_dict(row: Any, events: list[Event], features: dict[str, Any] | None = None,
                 user_actions: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    return {"id": row["id"], "label": row["label"], "created_at": row["created_at"], "data_origin": row["data_origin"],
            "status": row["status"], "duration_ms": row["duration_ms"], "seed": row["seed"],
            "engine_version": row["engine_version"], "app_version": row["app_version"],
            "config": json.loads(row["config_json"]), "source_text": row["source_text"], "final_text": row["final_text"],
            "events": [{"seq": e.seq, "t_ms": e.t_ms, "kind": e.kind, "source": e.source, "pos": e.pos, "removed": e.removed,
                        "inserted": e.inserted, "duration_ms": e.duration_ms, "meta": e.meta} for e in events],
            **({"features": features} if features is not None else {}),
            **({"user_actions": [{**a, "source": "captured"} for a in user_actions]} if user_actions is not None else {})}


def _fmt(v: Any) -> str:
    if v is None:
        return "Not recorded"
    if isinstance(v, float):
        return f"{v:.4g}"
    if isinstance(v, (dict, list)):
        return json.dumps(v, ensure_ascii=False, sort_keys=True)[:200]
    return str(v)


def report_markdown(title: str, origin: str, features: dict[str, dict[str, Any]], versions: list[dict[str, Any]]) -> str:
    lines = [f"# {title}", "", f"> **Data origin: {origin.upper()}.** {ORIGIN_TEXT.get(origin, '')}", "",
             f"Generated by Writing Process Lab {APP_VERSION} (engine {ENGINE_VERSION}). Metrics are descriptive "
             "observations; none of them establishes how a document was produced.", "", "## Revision summary", "",
             "| Version | Time (ms) | Chars | Words | Added | Removed | Since previous (ms) | Source |", "|---|---|---|---|---|---|---|---|"]
    for v in versions:
        lines.append(f"| {v['label']} | {_fmt(v['t_ms'])} | {v['chars']} | {v['words']} | {_fmt(v['added_chars'])} | "
                     f"{_fmt(v['removed_chars'])} | {_fmt(v['elapsed_since_prev_ms'])} | {v['data_source']} |")
    lines += ["", "## Metrics", "", "| Extractor | Metric | Status | Value |", "|---|---|---|---|"]
    for ex_id, r in features.items():
        for f in r["features"]:
            lines.append(f"| {ex_id} {r['version']} | {f['name']} | {f['status']} | {_fmt(f['value']).replace('|', '/')} |")
    return "\n".join(lines) + "\n"


def report_html(title: str, origin: str, features: dict[str, dict[str, Any]], versions: list[dict[str, Any]]) -> str:
    md = report_markdown(title, origin, features, versions)
    return ("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta http-equiv=\"Content-Security-Policy\" "
            "content=\"default-src 'none'; style-src 'unsafe-inline'\"><title>" + html.escape(title) +
            "</title><style>body{font:15px/1.5 system-ui;max-width:900px;margin:2em auto;padding:0 1em}pre{white-space:pre-wrap}"
            "</style></head><body><pre>" + html.escape(md) + "</pre></body></html>")


def unique_path(path: str | Path) -> Path:
    """Never overwrite: returns path, or 'name (1).ext', 'name (2).ext', ..."""
    p = Path(path)
    if not p.exists():
        return p
    for i in range(1, 10_000):
        cand = p.with_name(f"{p.stem} ({i}){p.suffix}")
        if not cand.exists():
            return cand
    raise FileExistsError(str(p))


def write_new(path: str | Path, content: str) -> Path:
    """Write text to a new file (exclusive create). Returns the path actually used."""
    p = unique_path(path)
    with open(p, "x", encoding="utf-8", newline="") as fh:
        fh.write(content)
    return p


def sha256_text(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8")).hexdigest()
